}

.menu-apps {
  flex: 1;
  padding: 8px;
  overflow-y: auto;
  display: flex;
  flex-direction: column;
  gap: 4px;
}

.app-item {
  padding: 8px 12px;
  border-radius: 6px;
  color: var(--text-main);
  font-size: 0.85rem;
