#!/usr/bin/env python3
"""
PC Self-Defense & Anti-Tamper Guardian for MintPilot
Protects the agent's core processes, configuration files, systemd services,
SSH keys, and root privileges against tampering, deletion, or hijacking.
"""

import os
import hashlib
import json
from pathlib import Path
from typing import Dict, Any, List

ROOT_DIR = Path(__file__).resolve().parent.parent.parent
AGENT_DIR = ROOT_DIR / "agent"
TRIPWIRE_DB = AGENT_DIR / "config" / "integrity_hashes.json"


class SelfDefenseGuardian:
    """Guards the agent and critical system files against tampering."""

    CRITICAL_FILES = [
        AGENT_DIR / "main.py",
        AGENT_DIR / "cli.py",
        AGENT_DIR / "brain" / "inference.py",
        AGENT_DIR / "core" / "permission_manager.py",
        AGENT_DIR / "config" / "settings.json",
        ROOT_DIR / "iso_builder" / "configs" / "mint-agent.service"
    ]

    def __init__(self):
        self.tripwire_db = TRIPWIRE_DB
        self._ensure_integrity_baseline()

    def _hash_file(self, filepath: Path) -> str:
        """Computes SHA-256 hash of a file."""
        if not filepath.exists():
            return "FILE_MISSING"
        h = hashlib.sha256()
        with open(filepath, "rb") as f:
            while chunk := f.read(8192):
                h.update(chunk)
        return h.hexdigest()

    def _ensure_integrity_baseline(self):
        """Creates an initial cryptographic tripwire baseline if not present."""
        if not self.tripwire_db.exists():
            baseline = {}
            for path in self.CRITICAL_FILES:
                if path.exists():
                    baseline[str(path)] = self._hash_file(path)
            self.tripwire_db.parent.mkdir(parents=True, exist_ok=True)
            with open(self.tripwire_db, "w", encoding="utf-8") as f:
                json.dump(baseline, f, indent=2)

    def verify_integrity(self) -> Dict[str, Any]:
        """Verifies cryptographic hashes against the verified baseline."""
        if not self.tripwire_db.exists():
            self._ensure_integrity_baseline()

        with open(self.tripwire_db, "r", encoding="utf-8") as f:
            baseline = json.load(f)

        tampered_files = []
        verified_count = 0

        for path_str, expected_hash in baseline.items():
            path = Path(path_str)
            if not path.exists():
                tampered_files.append({"file": path_str, "status": "deleted_or_missing"})
                continue
            current_hash = self._hash_file(path)
            if current_hash != expected_hash:
                tampered_files.append({
                    "file": path_str,
                    "status": "hash_mismatch_modified",
                    "expected": expected_hash[:12] + "...",
                    "current": current_hash[:12] + "..."
                })
            else:
                verified_count += 1

        is_intact = len(tampered_files) == 0
        return {
            "status": "secure" if is_intact else "tampering_detected",
            "is_intact": is_intact,
            "verified_files": verified_count,
            "tampered_files": tampered_files
        }

    def update_integrity_baseline(self) -> Dict[str, Any]:
        """Updates baseline hashes after an intentional authorized code upgrade."""
        baseline = {}
        for path in self.CRITICAL_FILES:
            if path.exists():
                baseline[str(path)] = self._hash_file(path)
        with open(self.tripwire_db, "w", encoding="utf-8") as f:
            json.dump(baseline, f, indent=2)
        return {"status": "baseline_updated", "count": len(baseline)}

    def audit_credentials_and_privileges(self) -> Dict[str, Any]:
        """Audits SSH keys, sudoers, and root permissions for privilege escalation."""
        findings = []

        # 1. SSH directory permissions
        ssh_dir = Path(os.path.expanduser("~/.ssh"))
        if ssh_dir.exists():
            stat_info = os.stat(ssh_dir)
            mode = oct(stat_info.st_mode)[-3:]
            if mode not in ["700", "750"]:
                findings.append({
                    "severity": "HIGH",
                    "issue": f"Insecure ~/.ssh directory permissions ({mode}). Should be 700.",
                    "fix": "chmod 700 ~/.ssh"
                })

            for key in ssh_dir.glob("id_*"):
                if not key.name.endswith(".pub"):
                    key_mode = oct(os.stat(key).st_mode)[-3:]
                    if key_mode not in ["600", "400"]:
                        findings.append({
                            "severity": "HIGH",
                            "issue": f"Insecure private key permissions for {key.name} ({key_mode}).",
                            "fix": f"chmod 600 {key}"
                        })

        # 2. Check /etc/sudoers.d/ for loose files
        sudoers_d = Path("/etc/sudoers.d")
        if sudoers_d.exists():
            for f in sudoers_d.iterdir():
                if f.is_file():
                    mode = oct(os.stat(f).st_mode)[-3:]
                    if mode != "440":
                        findings.append({
                            "severity": "CRITICAL",
                            "issue": f"Loose sudoers configuration file: {f.name} ({mode}). Must be 0440.",
                            "fix": f"sudo chmod 0440 {f}"
                        })

        return {
            "status": "secure" if not findings else "vulnerabilities_found",
            "findings_count": len(findings),
            "findings": findings
        }

#!/usr/bin/env python3
"""
Defensive Remediation & Cyber Hardening Engine for MintPilot
Provides autonomous threat neutralization, UFW firewall enforcement,
emergency lockdown, and CIS/SAIF security posture scoring.
"""

import os
import shutil
import subprocess
from typing import Dict, Any, List, Optional


class SecurityRemediation:
    """Executes defensive countermeasures and hardens Linux Mint."""

    def __init__(self):
        self._has_ufw = shutil.which("ufw") is not None
        self._has_iptables = shutil.which("iptables") is not None

    def get_firewall_status(self) -> Dict[str, Any]:
        """Queries UFW firewall state."""
        if not self._has_ufw:
            return {"status": "not_installed", "active": False}

        try:
            res = subprocess.run(["sudo", "-n", "ufw", "status"], capture_output=True, text=True)
            out = res.stdout.strip()
            is_active = "Status: active" in out
            return {
                "active": is_active,
                "status": "active" if is_active else "inactive",
                "rules": out.splitlines()[3:] if is_active else []
            }
        except Exception as e:
            return {"active": False, "status": "error", "error": str(e)}

    def enable_firewall(self) -> Dict[str, Any]:
        """Enforces default UFW defense: deny incoming, allow outgoing."""
        if not self._has_ufw:
            return {"error": "ufw not installed", "status": "failed"}

        try:
            subprocess.run(["sudo", "-n", "ufw", "default", "deny", "incoming"], check=True, capture_output=True)
            subprocess.run(["sudo", "-n", "ufw", "default", "allow", "outgoing"], check=True, capture_output=True)
            subprocess.run(["sudo", "-n", "ufw", "--force", "enable"], check=True, capture_output=True)
            return {"status": "success", "message": "UFW Firewall activated with strict default deny incoming."}
        except Exception as e:
            return {"error": str(e), "status": "failed"}

    def block_ip(self, ip_address: str) -> Dict[str, Any]:
        """Blocks all incoming and outgoing traffic to/from a hostile IP."""
        if not self._has_ufw:
            return {"error": "ufw not installed", "status": "failed"}

        try:
            subprocess.run(["sudo", "-n", "ufw", "insert", "1", "deny", "from", ip_address], check=True, capture_output=True)
            return {"status": "success", "blocked_ip": ip_address}
        except Exception as e:
            return {"error": str(e), "status": "failed"}

    def terminate_process(self, pid: int or str) -> Dict[str, Any]:
        """Immediately terminates a malicious or compromised process."""
        try:
            pid_int = int(pid)
            subprocess.run(["kill", "-9", str(pid_int)], check=True)
            return {"status": "success", "terminated_pid": pid_int}
        except Exception as e:
            return {"error": str(e), "status": "failed"}

    def emergency_lockdown(self) -> Dict[str, Any]:
        """
        Activates Emergency Lockdown Mode:
        1. Enables strict firewall dropping all incoming connections.
        2. Disables external file sharing services.
        3. Cleans temporary staging folders.
        """
        results = {}

        # 1. Firewall lockdown
        fw = self.enable_firewall()
        results["firewall"] = fw

        # 2. Block rogue temporary script execution
        try:
            subprocess.run(["sync"], check=True)
            results["filesystem_sync"] = "completed"
        except Exception:
            pass

        return {
            "status": "lockdown_active",
            "message": "Emergency PC Lockdown enforced. All incoming ports blocked.",
            "actions": results
        }

    def calculate_security_score(self, threat_summary: Dict[str, Any], integrity_summary: Dict[str, Any]) -> Dict[str, Any]:
        """
        Computes a comprehensive 0-100 Cybersecurity Hardening Score
        grounded in CIS Linux benchmarks and SAIF standards.
        """
        score = 100
        penalties = []

        # 1. Firewall check (30 pts)
        fw = self.get_firewall_status()
        if not fw.get("active"):
            score -= 25
            penalties.append("Firewall is inactive (-25 pts). Enable UFW to block inbound probes.")

        # 2. Critical Threats (30 pts each)
        crit_count = threat_summary.get("critical_count", 0)
        if crit_count > 0:
            deduct = min(40, crit_count * 30)
            score -= deduct
            penalties.append(f"{crit_count} Critical Threat(s) detected (-{deduct} pts).")

        # 3. High Network Exposure (10 pts per exposed port, max 30)
        high_count = threat_summary.get("high_count", 0)
        if high_count > 0:
            deduct = min(30, high_count * 8)
            score -= deduct
            penalties.append(f"{high_count} Insecure Port Exposure(s) on 0.0.0.0 (-{deduct} pts).")

        # 4. Agent Integrity (15 pts)
        if not integrity_summary.get("is_intact", True):
            score -= 20
            penalties.append("Core agent file tampering detected (-20 pts).")

        score = max(0, min(100, score))

        # Grade
        if score >= 90:
            grade = "A (Hardened)"
            color = "#2ecc71"
        elif score >= 75:
            grade = "B (Protected)"
            color = "#3498db"
        elif score >= 50:
            grade = "C (Exposed)"
            color = "#f39c12"
        else:
            grade = "F (High Risk)"
            color = "#e74c3c"

        return {
            "score": score,
            "grade": grade,
            "badge_color": color,
            "firewall_active": fw.get("active", False),
            "penalties": penalties,
            "recommendations": [
                "Run 'mint-agent --lockdown' to activate strict firewall defense",
                "Bind local development services to 127.0.0.1 instead of 0.0.0.0",
                "Ensure SSH directory permissions are set to 700"
            ] if score < 90 else ["System is in a hardened, protected posture."]
        }

#!/usr/bin/env python3
"""
MintPilot Offline Autonomous Brain & Tool Router
Combines sub-millisecond fast deterministic intent routing,
permission control (Turbo vs Safe Mode), memory safeguards (2GB-4GB RAM),
cybersecurity PC self-defense & threat protection, browser automation,
program control, and local SLM cognitive planning.
"""

import os
import re
import json
import time
import shutil
import subprocess
from typing import Dict, Any, List, Optional

from agent.core.permission_manager import PermissionManager
from agent.core.memory_guard import MemoryGuard
from agent.security.guardian import SecurityGuardian
from agent.controllers.system_control import SystemController
from agent.controllers.gui_control import GUIController
from agent.controllers.terminal_control import TerminalController
from agent.controllers.screen_vision import ScreenVisionController
from agent.controllers.voice_engine import VoiceEngine
from agent.controllers.browser_control import BrowserController
from agent.controllers.program_control import ProgramController


class AgentBrain:
    """The central intelligence coordinating perception, planning, permissions, security, and execution."""

    def __init__(self, model_path: Optional[str] = None, mode: Optional[str] = None):
        # Core Managers
        self.permissions = PermissionManager(mode=mode)
        self.memory = MemoryGuard()
        self.security = SecurityGuardian(self.permissions)

        # Controllers
        self.system = SystemController()
        self.gui = GUIController()
        self.terminal = TerminalController()
        self.vision = ScreenVisionController()
        self.voice = VoiceEngine()
        self.browser = BrowserController(self.gui)
        self.programs = ProgramController(self.gui)

        self.model_path = model_path
        self.hardware_tier = self._detect_hardware_tier()

    def _detect_hardware_tier(self) -> Dict[str, Any]:
        """Detects hardware capabilities and selects the optimal offline SLM tier."""
        mem_stats = self.memory.get_memory_stats()
        ram_mb = mem_stats.get("total_mb", 4000)
        has_gpu = shutil.which("nvidia-smi") is not None

        if ram_mb <= 4500:
